async function postSettlement(h){h.render().beginReview();const v=h.render();if(v.review)await v.confirm(v.review.token);}
function settlementCheck(title,run){test(`settlement workspace: ${title}`,async()=>{const h=settlementHarness.harness({args:[order.id,'/dashboard/orders']});try{h.respond((url,init)=>{if(init?.method==='POST'){const b=JSON.parse(init.body),fee=Number(b.expense_amount);return settlementHarness.ok({...settlementHarness.result,order_id:order.id,order_number:order.order_number,currency:'USD',gross_amount:'189',expense_amount:b.expense_amount,net_amount:(189-fee).toFixed(2),expense_id:fee?'synthetic-expense':null,expense_number:fee?'SYN-E':null,settlement_date:b.settlement_date||'2026-10-27',invoice_sent_to_client:b.mark_invoice_sent_to_client},201);}return settlementHarness.ok(url.endsWith('/settlement-meta')?{...settlementMeta,order_number:order.order_number}:url.endsWith('/settlement')?{...settlementHarness.state,...settlement}: {...order,status:'completed'});});h.render();await h.api().load();h.render();h.setupRequests=h.calls.splice(0);await run(h);}finally{h.cleanup();}});}
function check(kind,title,run){test(`${kind}: ${title}`,async()=>{const h=harness(kind);try{await run(h);}finally{h.cleanup();}});}
function ready(h,kind){h.render();h.set('loading',false);if(kind==='detail')h.set('order',{...order});if(kind==='commercial')h.set('summary',{...commercial});if(kind==='edit'){h.set('order',order);h.set('editState',{can_edit:true});}return h.render();}
function effect(h,pattern){const fn=h.effects.find(f=>pattern.test(f.toString()));assert.ok(fn,`effect ${pattern}`);return fn();}
function draft(h,kind){ready(h,kind);h.set('meta',meta);h.set('clientId',client.id);h.set('orderDate','2026-10-25');h.set('currency','USD');h.set('items',[{...item}]);return h.render();}
