check('list','quotation conversion blocks unaccepted source before any mutation',async h=>{h.query('quotation_id=synthetic%2Fquote');h.render();h.set('quotation',{id:'synthetic/quote',status:'sent'});h.render();await h.handlers().convertQuotation();assert.equal(h.requests.length,0);assert.match(h.state('error'),/Only accepted/);});
