check('new','bootstrap preserves metadata and client option limits',async h=>{h.render();effect(h,/Could not load order setup/);await settle();assert.deepEqual(h.requests.map(r=>r.url),['/api/sales/meta','/api/sales/client-options?limit=50']);assert.equal(h.state('currency'),'USD');assert.equal(h.state('items')[0].tax_rate,'5');assert.equal(h.state('loading'),false);});
check('detail','finance 403 clears settlement and suppresses every settlement action',async h=>{ready(h,'detail');h.set('order',{...order,status:'completed'});h.set('settlement',settlement);h.response(()=>failure(403));await h.handlers().loadSettlement();const tree=h.render();assert.equal(h.state('financeAccess'),false);assert.equal(h.state('settlement'),null);assert.equal(all(tree,'SettlementCard')[0].props.settlementHref,undefined);assert.equal(button(tree,'Create invoice & settle'),undefined);assert.equal(all(tree,'a').filter(a=>a.props.href?.includes('/settlement?')).length,0);assert.equal(h.requests.length,1);});
check('detail','finance 401 returns to login without creating a settlement',async h=>{ready(h,'detail');h.response(()=>failure(401));await h.handlers().loadSettlement();assert.deepEqual(h.navigation,[['replace','/login']]);assert.ok(h.requests.every(r=>!r.options?.method));});
check('detail','related CRM/project 403 masks do not invent linked records',async h=>{ready(h,'detail');h.response(url=>url.startsWith('/api/finance/')?success(settlement):failure(403));await h.handlers().loadRelated({...order,source_lead_id:'synthetic/lead'});assert.equal(h.state('lead'),null);assert.equal(h.state('project'),null);assert.equal(h.state('leadAccessRestricted'),true);assert.equal(h.state('projectAccessRestricted'),true);});
for(const [status,eligible,finance,expected]of [['confirmed',true,true,false],['completed',false,true,false],['completed',true,false,false],['completed',true,true,true]])check('detail',`settlement visibility ${status}/${eligible}/${finance}`,h=>{ready(h,'detail');h.set('order',{...order,status});h.set('settlement',{...settlement,eligible});h.set('financeAccess',finance);const tree=h.render();assert.equal(typeof all(tree,'SettlementCard')[0].props.settlementHref==='string',expected);assert.equal(all(tree,'a').some(a=>text(a).includes('Create invoice & settle')),expected);});
check('detail','stock remainder disables completion; posted fulfillment disables cancellation',h=>{ready(h,'detail');h.set('order',{...order,status:'in_progress',items:[stock]});const tree=h.render();assert.equal(h.handlers().stockRemaining,true);assert.equal(h.handlers().hasPostedFulfillment,true);assert.equal(button(tree,'Fulfill stock first').props.disabled,true);assert.equal(button(tree,'Cancel').props.disabled,true);});
for(const next of ['completed','in_progress'])check('detail',`${next==='completed'?'completion':'reopening'} confirmation Cancel makes no request`,async h=>{ready(h,'detail');h.set('order',{...order,status:next==='completed'?'in_progress':'completed'});h.render();h.confirm(false);assert.equal(await h.handlers().changeStatus(next),false);assert.equal(h.requests.length,0);assert.equal(h.confirmations.length,1);});
check('detail','status PATCH retains authoritative refresh and reopening message',async h=>{ready(h,'detail');h.set('order',{...order,status:'completed'});h.render();h.response((url,opts)=>url.endsWith('/status')?success({...order,status:'in_progress'}):h.defaultResponse(url,opts));assert.equal(await h.handlers().changeStatus('in_progress'),true);assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/status');assert.deepEqual(JSON.parse(h.requests[0].options.body),{status:'in_progress'});assert.match(h.state('message'),/reopened/);assert.equal(h.state('savingStatus'),false);});
check('detail','cancellation requires a reason and successful PATCH clears dialog state',async h=>{ready(h,'detail');h.set('cancelOpen',true);h.set('cancelReason',' x ');h.render();await h.handlers().confirmCancellation();assert.equal(h.requests.length,0);h.set('cancelReason',' Synthetic reason ');h.render();h.response(url=>url.endsWith('/status')?success({...order,status:'cancelled'}):h.defaultResponse(url));await h.handlers().confirmCancellation();assert.deepEqual(JSON.parse(h.requests[0].options.body),{status:'cancelled',reason:'Synthetic reason'});assert.equal(h.state('cancelOpen'),false);assert.equal(h.state('cancelReason'),'');});
check('detail','Keep order closes locally and does not change the authoritative order',h=>{ready(h,'detail');h.set('cancelOpen',true);button(h.render(),'Keep order').props.onClick();assert.equal(h.state('cancelOpen'),false);assert.equal(h.state('order').status,'confirmed');assert.equal(h.requests.length,0);});
settlementCheck('native settlement entry initializes original expense/marker/reference defaults and reads options only',async h=>{const v=h.render();assert.equal(v.values.markSent,false);assert.equal(v.values.expenseAmount,'0.00');assert.equal(v.values.reference,order.order_number);assert.equal(v.loading,false);assert.equal(h.setupRequests.length,3);assert.ok(h.setupRequests.some(r=>r.url==='/api/finance/orders/synthetic%2Forder/settlement-meta'));assert.ok(h.setupRequests.every(r=>!r.init?.method));});
for(const [name,patch,pattern]of [['no account',{accountId:''},/Select the account/],['negative expense',{expenseAmount:'-1'},/valid expense/],['nonfinite expense',{expenseAmount:'NaN'},/valid expense/],['expense cap',{expenseAmount:'189.01'},/cannot exceed/],['missing expense category',{expenseAmount:'1',categoryId:''},/expense category/]])settlementCheck(`settlement ${name} is rejected locally`,async h=>{h.api().change('accountId','synthetic-bank');for(const[k,v]of Object.entries(patch))h.api().change(k,v);h.render().beginReview();assert.equal(h.calls.length,0);assert.match(h.render().error,pattern);});
settlementCheck('settlement payload keeps expense precision, date, category, marker and reference',async h=>{for(const[k,v]of Object.entries({accountId:'synthetic-bank',date:'2026-10-25',expenseAmount:'10.126',categoryId:'synthetic-fee',description:' Synthetic fee ',reference:' SYN-REF ',markSent:true}))h.api().change(k,v);await postSettlement(h);const r=h.calls[0];assert.equal(r.url,'/api/finance/orders/synthetic%2Forder/settle');assert.equal(r.init.method,'POST');assert.deepEqual(JSON.parse(r.init.body),{account_id:'synthetic-bank',settlement_date:'2026-10-25',expense_amount:'10.13',expense_category_id:'synthetic-fee',expense_description:'Synthetic fee',mark_invoice_sent_to_client:true,reference:'SYN-REF'});assert.equal(h.render().phase,'acknowledged');assert.equal(h.api().result.expense_amount,'10.13');});
settlementCheck('zero-expense settlement sends null expense classification and default unsent marker',async h=>{for(const[k,v]of Object.entries({accountId:'synthetic-bank',categoryId:'stale-category',description:'stale-description'}))h.api().change(k,v);await postSettlement(h);const payload=JSON.parse(h.calls[0].init.body);assert.equal(payload.expense_amount,'0.00');assert.equal(payload.expense_category_id,null);assert.equal(payload.expense_description,null);assert.equal(payload.settlement_date,null);assert.equal(payload.mark_invoice_sent_to_client,false);});
settlementCheck('settlement failure retains document inputs and reports error without success text',async h=>{h.api().change('accountId','synthetic-bank');h.respond(()=>failure(409,'Synthetic settlement conflict'));await postSettlement(h);const v=h.render();assert.equal(v.values.accountId,'synthetic-bank');assert.equal(v.error,'Synthetic settlement conflict');assert.equal(v.result,null);assert.equal(v.phase,'rejected');});
check('detail','settlement net is gross minus every expense without cross-currency merging',h=>{ready(h,'detail');h.set('settlement',{...settlement,gross_amount:'189',expenses:[{amount:'10',currency:'USD'},{amount:'2.50',currency:'USD'}]});const card=all(h.render(),'SettlementCard')[0];assert.equal(card.props.expenseTotal,'12.50');assert.equal(card.props.net,'176.50');assert.equal(card.props.totalsUnavailable,false);});
check('commercial','load reads the encoded commercial endpoint and 401 routes to login',async h=>{h.render();await h.handlers().load();assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/commercial');assert.equal(h.state('summary').currency,'USD');h.response(()=>failure(401));await h.handlers().load();assert.deepEqual(h.navigation,[['replace','/login']]);});
check('commercial','scope change preserves signed type and exact decimal line payload',async h=>{ready(h,'commercial');h.set('changeOpen',true);h.set('changeType','reduction');h.set('changeTitle','Synthetic reduction');h.set('changeReason','Reason');h.set('changeLines',[{...item}]);h.render();await h.handlers().createChange();assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/changes');assert.deepEqual(JSON.parse(h.requests[0].options.body),{change_type:'reduction',title:'Synthetic reduction',reason:'Reason',items:[{...item,quantity:'2',unit_price:'100',discount_percent:'10',tax_rate:'5'}]});assert.equal(h.state('changeOpen'),false);assert.equal(h.state('changeTitle'),'');assert.equal(h.state('busy'),null);});
check('commercial','billing milestone payload preserves optional scope linkage and date',async h=>{ready(h,'commercial');h.set('billingOpen',true);h.set('billingTitle','Synthetic stage');h.set('billingDue','2026-11-01');h.set('billingOrderChangeId','approved-change');h.set('billingLines',[{...item}]);h.render();await h.handlers().createBilling();assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/billing-milestones');assert.deepEqual(JSON.parse(h.requests[0].options.body),{title:'Synthetic stage',due_date:'2026-11-01',order_change_id:'approved-change',items:[{...item,quantity:'2',unit_price:'100',discount_percent:'10',tax_rate:'5'}]});assert.equal(h.state('billingOpen'),false);assert.equal(h.state('billingOrderChangeId'),'');});
check('commercial','failed action retains form values and does not refresh as success',async h=>{ready(h,'commercial');h.set('changeOpen',true);h.set('changeTitle','Keep draft');h.render();h.response(()=>failure(422,'Synthetic constraint'));await h.handlers().createChange();assert.equal(h.state('changeOpen'),true);assert.equal(h.state('changeTitle'),'Keep draft');assert.equal(h.state('error'),'Synthetic constraint');assert.equal(h.requests.length,1);assert.equal(h.state('busy'),null);});
for(const [status,labels]of [['draft',['Submit for approval']],['pending',['Approve','Reject']],['approved',[]],['rejected',[]]])check('commercial',`scope ${status} exposes only allowed action callbacks`,async h=>{ready(h,'commercial');h.set('summary',{...commercial,changes:[{id:'change-1',change_number:'SYN-CH',title:'Synthetic scope',status,change_type:'addition',total:'20',effective_delta:'20',currency:'USD'}]});const tree=h.render();for(const label of ['Submit for approval','Approve','Reject'])assert.equal(Boolean(button(tree,label)),labels.includes(label));if(labels.length){await button(tree,labels[0]).props.onClick();await settle();assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/changes/change-1/action');assert.deepEqual(JSON.parse(h.requests[0].options.body),{action:status==='draft'?'submit':'approve'});}});
check('commercial','planned billing becomes billable and billable creates draft invoice with existing route',async h=>{ready(h,'commercial');const milestone={id:'bill-1',title:'Synthetic billing',currency:'USD',amount:'189',status:'planned',invoice_id:null};h.set('summary',{...commercial,billing_milestones:[milestone]});await button(h.render(),'Mark billable').props.onClick();await settle();assert.deepEqual(JSON.parse(h.requests[0].options.body),{action:'mark_billable'});h.set('summary',{...commercial,billing_milestones:[{...milestone,status:'billable'}]});h.response((url)=>url.endsWith('/invoice')?success({invoice_id:'synthetic-invoice'}):h.defaultResponse(url));await button(h.render(),'Create draft invoice').props.onClick();assert.deepEqual(h.navigation,[['push','/dashboard/accounting/invoices/synthetic-invoice']]);assert.equal(h.requests.at(-2).url,'/api/sales/orders/synthetic%2Forder/billing-milestones/bill-1/invoice');});
check('commercial','invoiced billing cannot be cancelled and retains invoice link',h=>{ready(h,'commercial');h.set('summary',{...commercial,billing_milestones:[{id:'bill',title:'Synthetic',status:'invoiced',invoice_id:'invoice-1',invoice_number:'SYN-I',currency:'USD',amount:'189'}]});const tree=h.render();assert.equal(button(tree,'Cancel'),undefined);assert.ok(all(tree,'a').some(n=>n.props.href==='/dashboard/accounting/invoices/invoice-1'));});
check('commercial','only approved changes are offered to new billing and empty titles stay disabled',h=>{ready(h,'commercial');h.set('billingOpen',true);h.set('changeOpen',true);h.set('summary',{...commercial,changes:[{id:'yes',status:'approved',title:'Approved',currency:'USD',effective_delta:'1'},{id:'no',status:'pending',title:'Pending',currency:'USD',effective_delta:'1'}]});const tree=h.render();assert.ok(all(tree,'option').some(n=>n.props.value==='yes'));assert.equal(all(tree,'option').some(n=>n.props.value==='no'),false);assert.equal(button(tree,'Create draft change').props.disabled,true);assert.equal(button(tree,'Create billing milestone').props.disabled,true);});
check('commercial','closing scope/billing draft panels performs no mutation',h=>{ready(h,'commercial');h.set('changeOpen',true);h.set('billingOpen',true);const tree=h.render();const toggles=all(tree,'button').filter(n=>n.props.onClick?.toString().includes('setChangeOpen')||n.props.onClick?.toString().includes('setBillingOpen'));assert.equal(toggles.length,2);toggles.forEach(n=>n.props.onClick());assert.equal(h.state('changeOpen'),false);assert.equal(h.state('billingOpen'),false);assert.equal(h.requests.length,0);});
check('fulfillment','service/non-stock lines do not create stock fulfillment controls',h=>{const tree=h.render({items:order.items});assert.match(text(tree),/No stock fulfillment required/);assert.equal(h.handlers().stockItems.length,0);assert.equal(all(tree,'form').length,0);});
check('fulfillment','load filters inactive warehouses and picks active default without replacing existing selection',async h=>{h.render();h.response(url=>url.endsWith('/warehouses')?success([{id:'inactive',is_active:false,is_default:true},{id:'first',is_active:true,is_default:false},{id:'default',is_active:true,is_default:true}]):success([]));await h.handlers().load();assert.deepEqual(h.state('warehouses').map(w=>w.id),['first','default']);assert.equal(h.state('warehouseId'),'default');h.set('warehouseId','first');h.render();await h.handlers().load();assert.equal(h.state('warehouseId'),'first');});
check('fulfillment','initial quantities derive only from remaining catalog stock',h=>{h.render({items:[stock,{...stock,id:'done',remaining_quantity:0},{...stock,id:'service',item_type_snapshot:'service'},{...stock,id:'no-product',product_id:null}]});h.effects[1]();assert.deepEqual(h.state('quantities'),{'stock-line':'3'});assert.equal(h.handlers().remainingItems.length,1);});
for(const [status,form]of [['confirmed',true],['in_progress',true],['completed',false],['cancelled',false]])check('fulfillment',`${status} dispatch form guard`,h=>{h.render();h.set('loading',false);assert.equal(all(h.render({status}),'form').length>0,form);});
for(const [name,warehouse,qty,pattern]of [['no warehouse','',2,/Choose a warehouse/],['no positive quantity','warehouse',0,/at least one/],['over remaining','warehouse',4,/exceeds/]])check('fulfillment',`${name} is rejected before posting`,async h=>{h.render();h.set('warehouseId',warehouse);h.set('quantities',{'stock-line':String(qty)});h.render();await h.handlers().submit({preventDefault(){}});assert.equal(h.requests.length,0);assert.match(h.state('error'),pattern);});
check('fulfillment','posting retains exact stock payload and generates a browser request key, not a proxy guarantee',async h=>{h.render();h.set('warehouseId','synthetic-warehouse');h.set('fulfillmentDate','2026-10-25');h.set('reference',' SYN-DISPATCH ');h.set('quantities',{'stock-line':'2'});h.render();h.response((url,opts)=>opts?.method==='POST'?success(fulfillment):h.defaultResponse(url));await h.handlers().submit({preventDefault(){}});const r=h.requests[0];assert.equal(r.url,'/api/sales/orders/synthetic%2Forder/fulfillments');assert.deepEqual(JSON.parse(r.options.body),{warehouse_id:'synthetic-warehouse',fulfillment_date:'2026-10-25',reference:'SYN-DISPATCH',items:[{order_item_id:'stock-line',quantity:2}]});assert.match(r.options.headers['Idempotency-Key'],/^fulfill-/);assert.deepEqual(h.notified,['SYN-F']);assert.equal(h.state('saving'),false);assert.equal(h.state('reference'),'');});
check('fulfillment','reversal requires a reason and retains exact encoded reversal payload',async h=>{h.render();h.handlers().beginReverse(fulfillment);h.render();await h.handlers().reverse(fulfillment);assert.equal(h.requests.length,0);assert.match(h.state('error'),/at least 3/);h.set('reverseReason',' Synthetic reversal ');h.set('reverseDate','2026-10-25');h.render();h.response((url,opts)=>opts?.method==='POST'?success({...fulfillment,status:'reversed'}):h.defaultResponse(url));await h.handlers().reverse(fulfillment);assert.equal(h.requests[0].url,'/api/sales/orders/synthetic%2Forder/fulfillments/synthetic%2Ffulfillment/reverse');assert.deepEqual(JSON.parse(h.requests[0].options.body),{reversal_date:'2026-10-25',reason:'Synthetic reversal'});assert.match(h.requests[0].options.headers['Idempotency-Key'],/^fulfill-reverse-/);assert.equal(h.state('reverseId'),null);assert.deepEqual(h.notified,['SYN-F reversed']);});
check('fulfillment','Keep fulfillment abandons local reversal without a request',h=>{h.render();h.set('loading',false);h.set('history',[fulfillment]);h.handlers().beginReverse(fulfillment);button(h.render(),'Keep fulfillment').props.onClick();assert.equal(h.state('reverseId'),null);assert.equal(h.state('reverseReason'),'');assert.equal(h.requests.length,0);});
check('fulfillment','reversed history and cancelled orders do not expose a reversal action',h=>{h.render();h.set('loading',false);h.set('history',[{...fulfillment,status:'reversed'}]);assert.equal(button(h.render(),'Reverse fulfillment'),undefined);h.set('history',[fulfillment]);assert.equal(button(h.render({status:'cancelled'}),'Reverse fulfillment'),undefined);});
check('fulfillment','server failure preserves pending stock quantities and releases busy state',async h=>{h.render();h.set('warehouseId','warehouse');h.set('quantities',{'stock-line':'1'});h.render();h.response(()=>failure(409,'Synthetic insufficient stock'));await h.handlers().submit({preventDefault(){}});assert.equal(h.state('error'),'Synthetic insufficient stock');assert.deepEqual(h.state('quantities'),{'stock-line':'1'});assert.equal(h.state('saving'),false);assert.equal(h.notified.length,0);});
check('list','single responsive register retains every commercial field, status and encoded open routes',h=>{
 const row={...order,id:'synthetic/order',subject:'Synthetic scope',quotation_number:'SYN-Q',status:'in_progress'};const tree=h.helpers.OrdersRegister({rows:[row],returnFor:()=>'/dashboard/orders?search=synthetic'});
 assert.equal(all(tree,'tbody')[0].props.children.length,1);for(const value of ['SYN-O','Synthetic scope','Synthetic client','SYN-Q','2026-10-25','USD 189.00'])assert.ok(text(tree).includes(value),value);
 assert.equal(all(tree,'StatusBadge')[0].props.status,'in_progress');assert.deepEqual(all(tree,'a').map(n=>n.props.href),['/dashboard/orders/synthetic%2Forder?returnTo=%2Fdashboard%2Forders%3Fsearch%3Dsynthetic','/dashboard/orders/synthetic%2Forder?returnTo=%2Fdashboard%2Forders%3Fsearch%3Dsynthetic']);
});
check('list','New order action lives on list and passes loaded rows without changing data',h=>{ready(h,'list');h.set('rows',[order]);const tree=h.render();assert.equal(all(tree,'a').filter(n=>n.props.href==='/dashboard/orders/new?returnTo=%2Fdashboard%2Forders').length,1);assert.deepEqual(all(tree,'OrdersRegister')[0].props.rows,[order]);});
check('layout','nested route wrapper retains Suspense children and no duplicate New order action',h=>{for(const route of ['/dashboard/orders','/dashboard/orders/new','/dashboard/orders/synthetic%2Forder']){h.pathname(route);const tree=h.render();assert.equal(all(tree,'a').length,0);assert.equal(all(tree,'Suspense')[0].props.children,'Synthetic child');}});
check('workspace','detail and commercial links remain encoded and edit action remains detail-only',h=>{h.pathname('/dashboard/orders/synthetic%2Forder');let links=all(h.render(),'a').map(n=>n.props.href);assert.deepEqual(links.map(url=>new URL(url,'https://example.invalid').pathname),['/dashboard/orders/synthetic%2Forder','/dashboard/orders/synthetic%2Forder/commercial','/dashboard/orders/synthetic%2Forder/edit']);h.pathname('/dashboard/orders/synthetic%2Forder/commercial');links=all(h.render(),'a').map(n=>n.props.href);assert.equal(links.length,2);});
for(const kind of ['new','edit'])check(kind,'shared summary receives the current computed amount, currency, date and tax mode',h=>{draft(h,kind);h.set('taxMode','inclusive');const summary=all(h.render(),'OrderEditorSummary')[0];assert.equal(summary.props.currency,'USD');assert.equal(summary.props.date,'2026-10-25');assert.equal(summary.props.taxMode,'inclusive');assert.match(text(summary.props.amount),/180\.00/);});
// A synthetic already-loaded draft fixture; authoritative setup initialization is tested separately.
function cleanDraft(h,kind){draft(h,kind);h.set('cleanSnapshot',h.handlers().draftSnapshot);return h.render();}
for(const kind of ['new','edit']){
 check(kind,'loaded draft fixture is clean; changing and restoring data tracks dirty state',h=>{cleanDraft(h,kind);assert.equal(h.handlers().hasChanges,false);h.set('subject','Local change');h.render();assert.equal(h.handlers().hasChanges,true);h.set('subject','');h.render();assert.equal(h.handlers().hasChanges,false);assert.equal(h.requests.length,0);});
 for(const[field,value]of Object.entries({clientId:'other-client',orderDate:'2026-10-26',currency:'BDT',taxMode:'inclusive',assignedEmployeeId:'employee',orderSource:'upwork',externalOrderId:'OTHER-REF',notes:'Client note',terms:'Terms change',internalNotes:'Internal change',items:[{...item,quantity:'3'}]}))check(kind,`dirty tracking includes ${field}`,h=>{cleanDraft(h,kind);h.set(field,value);h.render();assert.equal(h.handlers().hasChanges,true);});
 check(kind,'save failure retains input and dirty state without navigation or clearing guard',async h=>{cleanDraft(h,kind);h.set('notes','Keep my notes');h.render();const before=h.handlers().draftSnapshot;h.response(()=>failure(422,'Synthetic save rejected'));await h.handlers()[kind==='new'?'submit':'save']();h.render();assert.equal(h.handlers().draftSnapshot,before);assert.equal(h.handlers().hasChanges,true);assert.equal(h.state('saving'),false);assert.equal(h.navigation.length,0);assert.equal(h.guardCalls.some(c=>c.kind==='clean'),false);});
 check(kind,'synchronous duplicate saves make one mutation and clear dirty only after success',async h=>{cleanDraft(h,kind);h.set('notes','Changed');h.render();let resolve;h.response(()=>new Promise(r=>{resolve=r;}));const first=h.handlers()[kind==='new'?'submit':'save'](),second=h.handlers()[kind==='new'?'submit':'save']();assert.equal(h.requests.length,1);h.render();assert.equal(h.handlers().hasChanges,true);assert.equal(h.guardCalls.filter(c=>c.kind==='state').at(-1).options.isBusy,true);resolve(success(order));await Promise.all([first,second]);h.render();assert.equal(h.requests.length,1);assert.equal(h.handlers().hasChanges,false);assert.equal(h.state('saving'),false);assert.ok(h.guardCalls.some(c=>c.kind==='clean'));assert.deepEqual(h.navigation,[['navigate','/dashboard/orders/synthetic%2Forder?returnTo=%2Fdashboard%2Forders',{discard:true,...(kind==='new'?{replace:true}:{})}]]);});
 check(kind,'every editing control is disabled while saving while catalog identity locks remain',h=>{draft(h,kind);h.set('saving',true);const tree=h.render();const controls=['input','select','textarea','SearchableSelect','CurrencySelect','MoneyInput'].flatMap(type=>all(tree,type));assert.ok(controls.length>=10);for(const control of controls)assert.equal(control.props.disabled,true,`${control.type?.name||control.type}: ${control.props.name||control.props.label||control.props.type||''}`);assert.equal(all(tree,'button').filter(n=>n.props.onClick).every(n=>n.props.disabled===true),true);});
 check(kind,'new currency clears stale options and canceled old request cannot restore them',async h=>{draft(h,kind);h.set('catalog',[{id:'stale'}]);const pending=[];h.response(url=>new Promise(resolve=>pending.push({url,resolve})));const first=effect(h,/catalog-options\?currency/);assert.deepEqual(h.state('catalog'),[]);h.set('currency','EUR');h.render();first();effect(h,/catalog-options\?currency/);pending[1].resolve(success([{id:'eur',currency:'EUR'}]));await settle();pending[0].resolve(success([{id:'usd',currency:'USD'}]));await settle();assert.deepEqual(h.state('catalog'),[{id:'eur',currency:'EUR'}]);});
 check(kind,'unmounted initial setup cannot populate state or late error',async h=>{h.render();const unmount=effect(h,/mountedRef.current = true/);const pending=[];h.response(()=>new Promise(resolve=>pending.push(resolve)));effect(h,kind==='new'?/Could not load order setup/:/manual-edit-state/);unmount();pending.forEach(resolve=>resolve(failure(403,'Late denied')));await settle();assert.equal(h.state('meta'),null);assert.equal(h.state('error'),null);if(kind==='edit')assert.equal(h.state('order'),null);});
 check(kind,'Back and Cancel are native document anchors for dirty navigation capture',h=>{const tree=draft(h,kind);const exits=all(tree,'a').filter(n=>/Back|Cancel/.test(text(n)));assert.ok(exits.length>=1);assert.ok(exits.every(n=>n.props.href.startsWith('/dashboard/orders')));assert.equal(h.requests.length,0);});
}
