check('list','currency summary chips keep independent values without combining totals',h=>{const values=[{currency:'USD',amount:'100'},{currency:'BDT',amount:'200'},{currency:'EUR',amount:'300'}];const tree=h.helpers.Stat({label:'Total',value:3,values,icon:'Icon'});for(const value of ['USD 100','BDT 200','EUR 300'])assert.ok(text(tree).includes(value),value);assert.equal(text(tree).includes('600'),false);assert.equal(all(tree,'strong')[0].props.children,3);});
function dialogEnvironment(){
 const original={document:global.document,Node:global.Node,HTMLElement:global.HTMLElement};const listeners=new Map();
 class FakeNode{}
 class Element extends FakeNode{constructor(){super();this.isConnected=true;this.focuses=0;this.hidden=false;}focus(){this.focuses++;global.document.activeElement=this;}getClientRects(){return this.hidden?[]:[{}];}closest(){return null;}}
 const before=new Element(),first=new Element(),last=new Element(),outside=new Element(),dialog=new Element();let controls=[first,last],expanded=false;
 dialog.querySelectorAll=()=>controls;dialog.querySelector=()=>expanded?first:null;dialog.contains=node=>node===dialog||controls.includes(node);
 global.Node=FakeNode;global.HTMLElement=Element;global.document={activeElement:before,addEventListener:(type,fn)=>listeners.set(type,fn),removeEventListener:type=>listeners.delete(type)};
 return{before,first,last,outside,dialog,listeners,setControls:value=>{controls=value;},setExpanded:value=>{expanded=value;},event:(key,attrs={})=>({key,currentTarget:dialog,defaultPrevented:false,preventDefault(){this.defaultPrevented=true;},...attrs}),cleanup:()=>Object.assign(global,original)};
}
check('detail','dialog Escape closes only when idle and does not steal expanded select Escape',h=>{const d=dialogEnvironment();try{let closed=0;h.helpers.orderDialogKeyDown(d.event('Escape'),false,()=>closed++);assert.equal(closed,1);h.helpers.orderDialogKeyDown(d.event('Escape'),true,()=>closed++);assert.equal(closed,1);d.setExpanded(true);const event=d.event('Escape');h.helpers.orderDialogKeyDown(event,false,()=>closed++);assert.equal(closed,1);assert.equal(event.defaultPrevented,false);}finally{d.cleanup();}});
check('detail','dialog Tab and Shift+Tab wrap at visible controls',h=>{const d=dialogEnvironment();try{global.document.activeElement=d.last;const next=d.event('Tab');h.helpers.orderDialogKeyDown(next,false,()=>{});assert.equal(next.defaultPrevented,true);assert.equal(global.document.activeElement,d.first);const previous=d.event('Tab',{shiftKey:true});h.helpers.orderDialogKeyDown(previous,false,()=>{});assert.equal(previous.defaultPrevented,true);assert.equal(global.document.activeElement,d.last);}finally{d.cleanup();}});
check('detail','dialog with no visible controls focuses itself and ignores already-handled events',h=>{const d=dialogEnvironment();try{d.setControls([]);h.helpers.orderDialogKeyDown(d.event('Tab'),false,()=>{});assert.equal(global.document.activeElement,d.dialog);let closed=0;h.helpers.orderDialogKeyDown(d.event('Escape',{defaultPrevented:true}),false,()=>closed++);assert.equal(closed,0);}finally{d.cleanup();}});
check('detail','dialog mount contains focus and cleanup restores its connected trigger',h=>{const d=dialogEnvironment();try{h.render();const tree=h.helpers.OrderDialog({label:'Synthetic dialog',busy:false,onClose(){},className:'',children:'Synthetic'});tree.props.ref.current=d.dialog;const cleanup=h.effects.at(-1)();assert.equal(global.document.activeElement,d.first);d.outside.focus();d.listeners.get('focusin')({target:d.outside});assert.equal(global.document.activeElement,d.first);cleanup();assert.equal(global.document.activeElement,d.before);assert.equal(d.listeners.has('focusin'),false);}finally{d.cleanup();}});
check('detail','cancellation dialog keeps busy/close semantics; settlement editor is no longer inline',h=>{ready(h,'detail');h.set('cancelOpen',true);h.set('savingStatus',true);const dialogs=all(h.render(),'OrderDialog');assert.equal(dialogs.length,1);assert.equal(dialogs[0].props.busy,true);h.set('savingStatus',false);all(h.render(),'OrderDialog')[0].props.onClose();assert.equal(h.state('cancelOpen'),false);assert.equal(h.requests.length,0);assert.equal(all(h.render(),'input').length,0);});
function navigationHelpers(){const file=path.join(root,'src/lib/order-navigation.ts'),m=new Module(file,module);m.filename=file;m.paths=module.paths;m._compile(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,file);return m.exports;}
const orderNav=navigationHelpers();
for(const bad of [null,undefined,'','https://other.invalid/dashboard/orders','//other.invalid','/dashboard/quotations','/dashboard/orders/new','/dashboard/orders/other','javascript:alert(1)','/dashboard/orders#fragment','/dashboard/orders?returnTo=https%3A%2F%2Fother.invalid'])test(`order navigation: unsafe/non-register return ${JSON.stringify(bad)} becomes register`,()=>assert.equal(orderNav.safeOrderReturnHref(bad),'/dashboard/orders'));
for(const status of ['confirmed','in_progress','completed','cancelled'])test(`order navigation: valid ${status} filter persists`,()=>assert.equal(orderNav.safeOrderReturnHref(`/dashboard/orders?status=${status}`),`/dashboard/orders?status=${status}`));
test('order navigation: search, page count and focus are sanitized and other query fields removed',()=>{const result=orderNav.safeOrderReturnHref('/dashboard/orders?search=++A+%26+B++&status=sent&pages=999&focus=synthetic%2Forder&order_id=old&quotation_id=quote');assert.equal(result,'/dashboard/orders?search=A+%26+B&pages=999&focus=synthetic%2Forder');assert.equal(orderNav.safeOrderReturnHref('/dashboard/orders?pages=-2&status=unknown'),'/dashboard/orders');assert.equal(orderNav.safeOrderReturnHref('/dashboard/orders?pages=not-a-number'),'/dashboard/orders');const long=new URL(orderNav.safeOrderReturnHref(`/dashboard/orders?search=${'x'.repeat(510)}&focus=${'y'.repeat(210)}`),'https://example.invalid');assert.equal(long.searchParams.get('search').length,500);assert.equal(long.searchParams.get('focus').length,200);});
for(const mode of ['view','edit','commercial'])test(`order navigation: ${mode} path encodes identity and preserves only safe list context`,()=>{const url=orderNav.orderDocumentHref('synthetic/order ?#',mode,'/dashboard/orders?search=scope&status=completed&pages=2');const parsed=new URL(url,'https://example.invalid');assert.equal(parsed.pathname,`/dashboard/orders/synthetic%2Forder%20%3F%23${mode==='view'?'':`/${mode}`}`);assert.equal(orderNav.orderReturnHref(parsed.search),'/dashboard/orders?search=scope&status=completed&pages=2');});
test('order navigation: create and direct document defaults use register rather than arbitrary returnTo',()=>{assert.equal(orderNav.orderCreateHref('https://other.invalid'),'/dashboard/orders/new?returnTo=%2Fdashboard%2Forders');assert.equal(orderNav.orderReturnHref('?returnTo=%2Fdashboard%2Forders%2Fnew'),'/dashboard/orders');assert.equal(orderNav.orderDocumentHref(42),'/dashboard/orders/42?returnTo=%2Fdashboard%2Forders');});
check('list','direct pages query sequentially restores cursor history, never persists customer data',async h=>{h.query('search=scope&status=completed&pages=3');h.render();let page=0;h.response(()=>success({items:[{...order,id:String(++page)}],next_cursor:page<3?`cursor ${page}`:null}));effect(h,/cached.length < pages/);await settle();assert.equal(h.requests.length,3);assert.deepEqual(h.requests.map(r=>new URL(r.url,'https://example.invalid').searchParams.get('cursor')),[null,'cursor 1','cursor 2']);assert.deepEqual(h.state('rows').map(row=>row.id),['1','2','3']);assert.equal(h.handlers().pageCache.current.query,'limit=30&search=scope&status=completed');});
check('list','Back to a cached earlier page removes appended rows without refetch; Forward reuses cache',async h=>{h.query('pages=2');h.render();let page=0;h.response(()=>success({items:[{...order,id:String(++page)}],next_cursor:page===1?'second':null}));effect(h,/cached.length < pages/);await settle();assert.equal(h.requests.length,2);h.query('');h.render();effect(h,/cached.length < pages/);await settle();assert.deepEqual(h.state('rows').map(row=>row.id),['1']);assert.equal(h.state('nextCursor'),'second');h.query('pages=2');h.render();effect(h,/cached.length < pages/);await settle();assert.deepEqual(h.state('rows').map(row=>row.id),['1','2']);assert.equal(h.requests.length,2);});
