 const file=path.join(root,'src/app/dashboard/page.tsx'),source=fs.readFileSync(file,'utf8'),ast=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);const fn=ast.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text==='WorkspaceLink');assert.ok(fn);const m=new Module(file,module);m.filename=file;m.paths=module.paths;m._compile(ts.transpileModule('const Link="NextLink";const ArrowRight="ArrowRight";'+fn.getText(ast)+';export {WorkspaceLink};',{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX}}).outputText,file);
 for(const href of ['/dashboard/orders/new','/dashboard/accounting/money-in','/dashboard/accounting/money-out','/dashboard/accounting/transfers']){const tree=m.exports.WorkspaceLink({href,label:'Synthetic action',icon:'Icon'});assert.equal(tree.type,href==='/dashboard/orders/new'?'a':'NextLink');assert.equal(tree.props.href,href);assert.equal(tree.props.prefetch,href==='/dashboard/orders/new'?undefined:false);}
