 check(kind,'authoritative setup initializes a clean baseline before the loaded form is editable',async h=>{h.render();effect(h,kind==='new'?/Could not load order setup/:/manual-edit-state/);await settle();h.render();assert.equal(h.state('loading'),false);assert.notEqual(h.state('cleanSnapshot'),null);assert.equal(h.state('cleanSnapshot'),h.handlers().draftSnapshot);assert.equal(h.handlers().hasChanges,false);const original=h.state('notes');h.set('notes','Synthetic local note');h.render();assert.equal(h.handlers().hasChanges,true);h.set('notes',original);h.render();assert.equal(h.handlers().hasChanges,false);});
 check(kind,'return context derives immediately from route search without an initialization effect',h=>{draft(h,kind);h.query(new URLSearchParams({returnTo:'/dashboard/orders?search=first&status=confirmed&pages=2'}));h.render();assert.equal(h.handlers().returnHref,'/dashboard/orders?search=first&status=confirmed&pages=2');h.query(new URLSearchParams({returnTo:'https://other.invalid'}));h.render();assert.equal(h.handlers().returnHref,'/dashboard/orders');assert.equal(h.requests.length,0);});
